(function(){
  function rand(a,b){return a+Math.random()*(b-a);}
  let particles=[];
  const N=64;
  function spawn(){
    const w=W(), h=H();
    const zone = Math.random()<0.5 ? 'top':'bottom';
    let y;
    if(zone==='top') y = rand(-0.05,0.28)*h; else y = rand(0.72,1.05)*h;
    return {
      x: rand(0,w), y:y, z:zone,
      size: rand(4,13),
      speed: rand(0.05,0.16),
      drift: rand(-0.25,0.25),
      angle: rand(0,Math.PI*2),
      spin: rand(-0.008,0.008),
      alpha: rand(0.25,0.7),
      hue: PALETTE[Math.floor(Math.random()*PALETTE.length)],
      type: Math.random()<0.6 ? 'petal':'note',
      phase: rand(0,Math.PI*2)
    };
  }
  for(let i=0;i<N;i++) particles.push(spawn());

  function drawPetal(p){
    ctx.save();
    ctx.translate(p.x,p.y);
    ctx.rotate(p.angle);
    ctx.globalAlpha = p.alpha;
    ctx.beginPath();
    ctx.fillStyle = p.hue;
    ctx.moveTo(0,-p.size);
    ctx.bezierCurveTo(p.size*0.8,-p.size*0.4, p.size*0.6,p.size*0.6, 0,p.size);
    ctx.bezierCurveTo(-p.size*0.6,p.size*0.6, -p.size*0.8,-p.size*0.4, 0,-p.size);
    ctx.fill();
    ctx.restore();
  }
  function drawNote(p){
    ctx.save();
    ctx.translate(p.x,p.y);
    ctx.rotate(p.angle*0.3);
    ctx.globalAlpha = p.alpha*0.85;
    ctx.fillStyle = p.hue;
    ctx.beginPath();
    ctx.ellipse(0,0,p.size*0.5,p.size*0.35,0.5,0,Math.PI*2);
    ctx.fill();
    ctx.fillRect(p.size*0.4,-p.size*1.6,p.size*0.12,p.size*1.6);
    ctx.restore();
  }

  function frame(){
    const w=W(), h=H();
    ctx.clearRect(0,0,w,h);
    for(const p of particles){
      p.phase += 0.01;
      p.x += Math.sin(p.phase)*p.drift;
      p.y -= p.speed;
      p.angle += p.spin;
      if(p.z==='top'){
        if(p.y < -0.08*h){ p.y = 0.28*h; p.x = Math.random()*w; }
      } else {
        if(p.y < 0.66*h){ p.y = 1.05*h; p.x = Math.random()*w; }
      }
      ctx.shadowBlur = 8;
      ctx.shadowColor = p.hue;
      if(p.type==='petal') drawPetal(p); else drawNote(p);
      ctx.shadowBlur = 0;
    }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
